from typing import Iterable, Mapping, Optional, Dict, Tuple
from stockflow.parse_movement_line import parse_movement_line

def on_hand_by_location(
    lines: Iterable[str], 
    case_sizes: Mapping[str, int], 
    as_of_day: Optional[int] = None
) -> Dict[Tuple[str, str], int]:
    """
    Compute on-hand stock per SKU and bin location from movement records.
    """
    totals: Dict[Tuple[str, str], int] = {}

    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        # parse_movement_line is expected to return (day, type, sku, location, qty_str)
        parsed = parse_movement_line(line)
        day, _, sku, location, qty_str = parsed

        if as_of_day is not None and day > as_of_day:
            continue

        sku_upper = sku.upper()

        parts = qty_str.split()
        if len(parts) != 2:
            raise ValueError(f"Invalid quantity format: {qty_str}")

        val = int(parts[0])
        unit = parts[1].upper()

        if unit == 'CS':
            amount = val * case_sizes.get(sku_upper, 0)
        elif unit == 'EA':
            amount = val
        else:
            raise ValueError(f"Unknown unit: {unit}")

        key = (sku_upper, location)
        totals[key] = totals.get(key, 0) + amount

    # Filter out zero balances to match typical inventory reports and the test diff
    return {k: v for k, v in totals.items() if v != 0}
